// === Tab: mySketch.js ===
/*
It is a 2D shader made for the weekly Creative Coding Challenge
(https://openprocessing.org/curation/78544) on the theme "Flip".

It flips between light and dark. It also creates the illusion
of switching between 2D and 3D, which it doesn't actually do.
*/

const scale = Math.max(1, devicePixelRatio)
let theShader

function preload(){
	theShader = loadShader('https://openprocessing.org/sketch/2918655/files/vert.glsl', 'frag.glsl')
}

function setup() {
	pixelDensity(scale)
	createCanvas(windowWidth, windowHeight, WEBGL)
}

function windowResized() {
	pixelDensity(scale)
	resizeCanvas(windowWidth, windowHeight)
}

function draw() {
  shader(theShader)
  theShader.setUniform("resolution", [width * scale, height * scale])
  theShader.setUniform("time", millis() / 1000.0)
  rect(0, 0, width, height)
}

// === Tab: vert.glsl ===
#version 300 es 
in vec3 aPosition; void main() { gl_Position=vec4(aPosition*2.-1., 1.0); }

// === Tab: frag.glsl ===
#version 300 es
/*********
* made by Matthias Hurrle (@atzedent)
*/
precision highp float;
out vec4 O;
uniform float time;
uniform vec2 resolution;
#define FC gl_FragCoord.xy
#define R resolution
#define T time
void main() {
	// center coordinate system
	vec2 uv=(FC-.5*R)/min(R.x,R.y), p=uv;
	// save scanline for later application
	float scanline=sin(T-uv.y*800.)*.01+.01;
	// domain repetition (grid)
	uv=fract(uv*4.)-.5;
	// shape inside the grid
	uv*=vec2(sin(1.+uv.x),cos(1.-uv.y));
	// k for the animation, f for the smooth transition
	float f=12.*dot(p,.2*p), k=sin(T*1.5-f)*dot(uv,uv);
	// apply color value based on k
	vec3 col=vec3(.6+.6*cos(6.3*k+2.));
	// apply scanline
	col+=scanline;
	// vignette
	col*=pow(1.-dot(p*.2,p*.2),18.);
	O=vec4(col,1);
}

